package com.northstarbank.entitlements;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;
class TokenServiceTest{private final TokenService tokens=new TokenService("01234567890123456789012345678901");@Test void mintedTokenResolvesOnlySignedUser(){StaffUser u=new StaffUser("EMP001","csr@test",Role.CSR,"B01","R1",BigDecimal.ZERO,BigDecimal.ZERO);String token=tokens.mint(u,"B01","0");assertEquals("EMP001",tokens.verifyAndGetUser(token));assertThrows(TokenService.InvalidTokenException.class,()->tokens.verifyAndGetUser(token+"x"));}}
